#pragma once

// Shared definitions of the TTT2 runtime: big-endian guest memory access, the guest
// calling convention bridge and the import macro.
//
// The host<->guest argument bridge follows Unleashed Recompiled's kernel/function.h
// (hedge-dev, GPL-3.0), simplified for this project.

#include "ppc_recomp_shared.h" // generated by XenonRecomp: PPCContext, PPC_FUNC, PPC_LOOKUP_FUNC

#include <atomic>
#include <bit>
#include <cstdint>
#include <cstring>
#include <string>
#include <type_traits>

namespace tt2
{
    extern uint8_t* g_base; // host address of guest address 0 (4 GB reservation)

    template <typename T>
    T byteswap(T v)
    {
        if constexpr (sizeof(T) == 1)
            return v;
        else if constexpr (sizeof(T) == 2)
            return std::bit_cast<T>(__builtin_bswap16(std::bit_cast<uint16_t>(v)));
        else if constexpr (sizeof(T) == 4)
            return std::bit_cast<T>(__builtin_bswap32(std::bit_cast<uint32_t>(v)));
        else
            return std::bit_cast<T>(__builtin_bswap64(std::bit_cast<uint64_t>(v)));
    }

    // A value stored big-endian in guest memory.
    template <typename T>
    struct be
    {
        T raw;
        T get() const { return byteswap(raw); }
        void set(T v) { raw = byteswap(v); }
        operator T() const { return get(); }
        be& operator=(T v)
        {
            set(v);
            return *this;
        }
    };
    static_assert(sizeof(be<uint32_t>) == 4);

    inline void* host_ptr(uint32_t guest) { return g_base + guest; }

    template <typename T>
    T* gptr(uint32_t guest)
    {
        return guest ? reinterpret_cast<T*>(g_base + guest) : nullptr;
    }

    inline uint32_t guest_addr(const void* host)
    {
        return host ? uint32_t(static_cast<const uint8_t*>(host) - g_base) : 0;
    }

    inline uint32_t load32(uint32_t a) { return reinterpret_cast<be<uint32_t>*>(g_base + a)->get(); }
    inline void store32(uint32_t a, uint32_t v) { reinterpret_cast<be<uint32_t>*>(g_base + a)->set(v); }
    inline uint16_t load16(uint32_t a) { return reinterpret_cast<be<uint16_t>*>(g_base + a)->get(); }
    inline void store16(uint32_t a, uint16_t v) { reinterpret_cast<be<uint16_t>*>(g_base + a)->set(v); }
    inline uint64_t load64(uint32_t a) { return reinterpret_cast<be<uint64_t>*>(g_base + a)->get(); }
    inline void store64(uint32_t a, uint64_t v) { reinterpret_cast<be<uint64_t>*>(g_base + a)->set(v); }

    inline PPCFunc* find_function(uint32_t guest) { return PPC_LOOKUP_FUNC(g_base, guest); }

    // The PPC context of the guest thread running on this host thread.
    PPCContext* current_context();
    void set_current_context(PPCContext* ctx);

    // Arguments of an import call, following the Xbox 360 ABI (r3-r10, then the caller's
    // parameter area at r1 + 0x54).
    struct Args
    {
        PPCContext& ctx;

        uint32_t u32(int i) const
        {
            switch (i)
            {
            case 0: return ctx.r3.u32;
            case 1: return ctx.r4.u32;
            case 2: return ctx.r5.u32;
            case 3: return ctx.r6.u32;
            case 4: return ctx.r7.u32;
            case 5: return ctx.r8.u32;
            case 6: return ctx.r9.u32;
            case 7: return ctx.r10.u32;
            default: return load32(ctx.r1.u32 + 0x54 + uint32_t(i - 8) * 8);
            }
        }
        uint64_t u64(int i) const
        {
            switch (i)
            {
            case 0: return ctx.r3.u64;
            case 1: return ctx.r4.u64;
            case 2: return ctx.r5.u64;
            case 3: return ctx.r6.u64;
            case 4: return ctx.r7.u64;
            case 5: return ctx.r8.u64;
            case 6: return ctx.r9.u64;
            case 7: return ctx.r10.u64;
            default: return load64(ctx.r1.u32 + 0x50 + uint32_t(i - 8) * 8);
            }
        }
        int32_t s32(int i) const { return int32_t(u32(i)); }
        template <typename T>
        T* ptr(int i) const { return gptr<T>(u32(i)); }
        double f64(int i) const { return (&ctx.f1)[i].f64; }

        void ret(uint64_t v) const { ctx.r3.u64 = v; }
    };

    // Calls a guest function from host code (callbacks: interrupts, audio, thread starts).
    // Uses the current guest thread's stack; must run on a thread with a guest context.
    template <typename... A>
    uint32_t call_guest(uint32_t function, A... args)
    {
        PPCContext* cur = current_context();
        PPCContext ctx{};
        ctx.r1 = cur->r1;
        ctx.r1.u64 -= 0x100; // leave the caller's red zone alone
        ctx.r13 = cur->r13;
        ctx.fpscr = cur->fpscr;
        uint64_t values[] = { uint64_t(args)..., 0 };
        PPCRegister* regs[] = { &ctx.r3, &ctx.r4, &ctx.r5, &ctx.r6, &ctx.r7, &ctx.r8, &ctx.r9, &ctx.r10 };
        for (size_t i = 0; i < sizeof...(A) && i < 8; i++)
            regs[i]->u64 = values[i];
        set_current_context(&ctx);
        find_function(function)(ctx, g_base);
        cur->fpscr = ctx.fpscr;
        set_current_context(cur);
        return ctx.r3.u32;
    }

    void log(const char* fmt, ...) __attribute__((format(printf, 1, 2)));
    std::string guest_backtrace(uint32_t r1, int depth); // main.cpp
    void watch_now(uint32_t address);                     // main.cpp: TT2_WATCH from code (debugging)
    [[noreturn]] void fatal(const char* fmt, ...) __attribute__((format(printf, 1, 2)));
}

// Defines the host implementation of a kernel/XAM import. The generated code calls
// __imp__<Name>; imports without a TT2_IMPORT get a logging stub (gen_import_stubs.cmake).
// With TT2_TRACE=1 in the environment every import call is logged (boot debugging).
namespace tt2
{
    extern bool g_trace_imports;
    void trace_import(const char* name, const PPCContext& ctx);
    // The import this thread is executing (shown by the thread dump), or null.
    extern thread_local const char* t_current_import;
    struct ImportScope
    {
        const char* previous;
        explicit ImportScope(const char* name) : previous(t_current_import) { t_current_import = name; }
        ~ImportScope() { t_current_import = previous; }
    };
}
#define TT2_IMPORT(name)                                         \
    static void tt2_impl_##name(PPCContext& ctx, uint8_t* base); \
    PPC_FUNC(__imp__##name)                                      \
    {                                                            \
        if (tt2::g_trace_imports) [[unlikely]]                   \
            tt2::trace_import(#name, ctx);                       \
        tt2::ImportScope tt2_scope(#name);                       \
        tt2_impl_##name(ctx, base);                              \
    }                                                            \
    static void tt2_impl_##name([[maybe_unused]] PPCContext& ctx, [[maybe_unused]] uint8_t* base)

// NTSTATUS / Win32 codes used by the imports
namespace tt2::status
{
    constexpr uint32_t success = 0x00000000;
    constexpr uint32_t wait_0 = 0x00000000;
    constexpr uint32_t abandoned_wait_0 = 0x00000080;
    constexpr uint32_t user_apc = 0x000000C0;
    constexpr uint32_t timeout = 0x00000102;
    constexpr uint32_t pending = 0x00000103;
    constexpr uint32_t object_name_exists = 0x40000000;
    constexpr uint32_t buffer_overflow = 0x80000005;
    constexpr uint32_t no_more_files = 0x80000006;
    constexpr uint32_t unsuccessful = 0xC0000001;
    constexpr uint32_t not_implemented = 0xC0000002;
    constexpr uint32_t invalid_handle = 0xC0000008;
    constexpr uint32_t invalid_parameter = 0xC000000D;
    constexpr uint32_t no_such_file = 0xC000000F;
    constexpr uint32_t end_of_file = 0xC0000011;
    constexpr uint32_t no_memory = 0xC0000017;
    constexpr uint32_t access_denied = 0xC0000022;
    constexpr uint32_t object_type_mismatch = 0xC0000024;
    constexpr uint32_t object_name_not_found = 0xC0000034;
    constexpr uint32_t object_name_collision = 0xC0000035;
    constexpr uint32_t object_path_not_found = 0xC000003A;
    constexpr uint32_t mutant_not_owned = 0xC0000046;
    constexpr uint32_t semaphore_limit_exceeded = 0xC0000047;
    constexpr uint32_t not_supported = 0xC00000BB;
    constexpr uint32_t device_not_connected = 0xC000009D;
}

namespace tt2::win32
{
    constexpr uint32_t success = 0;
    constexpr uint32_t file_not_found = 2;
    constexpr uint32_t access_denied = 5;
    constexpr uint32_t invalid_handle = 6;
    constexpr uint32_t no_more_files = 18;
    constexpr uint32_t device_not_connected = 1167;
    constexpr uint32_t cancelled = 1223;
    constexpr uint32_t io_pending = 997;
    constexpr uint32_t function_failed = 1627;
    constexpr uint32_t no_such_user = 1317;
    constexpr uint32_t not_logged_on = 1245;
}
